import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { shippedProfiles } from '../difficulty/shipped';
import { YamlDocument } from '../model/document';
import { describeOption } from '../renderer/state/options';
import { engineOptionsFor } from '../renderer/state/seedOptions';
import { seededRandom } from '../roulette/random';
import { parseSchemaFile } from '../schema/load';
import { planRandomizeAll } from './plan';
import { randomizableOptions, WIDE_RANGE } from './roll';

// data/schema.json is generated by scripts/extract-schema.ps1; skip until it exists.
const schemaUrl = new URL('../../data/schema.json', import.meta.url);
const schema = existsSync(schemaUrl) ? parseSchemaFile(readFileSync(schemaUrl, 'utf8')) : null;

describe.skipIf(schema === null)('randomize against the real schema', () => {
  const games = Object.values(schema?.games ?? {}).filter((g) => !g.hidden);

  it('every visible game rolls values that apply cleanly and show as ordinary, valid Simple-mode values', () => {
    let optionsRolled = 0;
    for (const game of games) {
      const plan = planRandomizeAll({
        game,
        apVersion: schema!.apVersion,
        profiles: shippedProfiles,
        current: {},
        locked: new Set(),
        random: seededRandom(game.name.length * 7919),
      });
      expect(plan.ok, `${game.name}: ${plan.ok ? '' : plan.message}`).toBe(true);
      if (!plan.ok) continue;
      const doc = YamlDocument.empty(game.name);
      doc.applyAll(plan.edits);
      expect(doc.isValid, game.name).toBe(true);
      for (const edit of plan.edits) {
        if (edit.op !== 'set') continue;
        const option = game.options[edit.option]!;
        const state = describeOption(option, doc.get(game.name, edit.option));
        expect(state.editable, `${game.name}.${edit.option} = ${JSON.stringify(edit.value)}`).toBe(true);
        expect(state.warning, `${game.name}.${edit.option} = ${JSON.stringify(edit.value)}`).toBeUndefined();
        optionsRolled += 1;
      }
    }
    expect(optionsRolled).toBeGreaterThan(1500);
  });

  it('leaves very wide number ranges alone', () => {
    for (const game of games) {
      for (const option of randomizableOptions(game)) {
        if (option.kind === 'range' || option.kind === 'named_range') {
          expect(option.max! - option.min! + 1, `${game.name}.${option.key}`).toBeLessThanOrEqual(WIDE_RANGE);
        }
      }
    }
    const pokemon = schema!.games['Pokemon Red and Blue']!;
    expect(randomizableOptions(pokemon).map((o) => o.key)).not.toContain('starting_money');
  });

  it('every game has something to randomize', () => {
    const empty = games.filter((g) => randomizableOptions(g).length === 0).map((g) => g.name);
    expect(empty).toEqual([]);
  });

  it('a difficulty band works for a rated game, and the result really is inside it', () => {
    const game = schema!.games['A Link to the Past']!;
    for (const [min, max] of [[2, 4], [5, 7], [7.5, 10]] as const) {
      const plan = planRandomizeAll({
        game,
        apVersion: schema!.apVersion,
        profiles: shippedProfiles,
        current: {},
        locked: new Set(),
        random: seededRandom(42),
        band: { min, max },
      });
      expect(plan.ok, `band ${min}-${max}: ${plan.ok ? '' : plan.message}`).toBe(true);
      if (!plan.ok) continue;
      const doc = YamlDocument.empty(game.name);
      doc.applyAll(plan.edits);
      const again = planRandomizeAll({ game, apVersion: schema!.apVersion, profiles: shippedProfiles, current: engineOptionsFor(doc, game.name, game), locked: new Set(Object.keys(game.options)), random: seededRandom(1), band: { min, max } });
      expect(again.ok).toBe(false); // everything locked: nothing to roll
      expect(plan.score).toBeGreaterThanOrEqual(min);
      expect(plan.score).toBeLessThanOrEqual(max);
    }
  });
});
